{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver vejledningens afsnit 4.3 korrekt: lægefaglige oplysninger om forløb og symptomer, epikriser/journalnotater, støtteafgørelser og skånehensyn, og at den personlige redegørelse kan bruges, hvis dokumentation mangler. Det indeholder ingen af rubrikkens væsentlige fejl, fx at helt ny dokumentation kræves, at alle dokumenttyper er obligatoriske, eller at redegørelsen erstatter det lægefaglige minimum."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med: seneste lægefaglige oplysninger (dog ikke sygehistorikken eksplicit), udrednings- og behandlingsforløb samt aktuelle symptomer, epikriser og journalnotater, støtteforanstaltninger/skånehensyn som supplement, og den personlige redegørelse. Sygehistorikken indgår i punkt 2 ('beskriver sygehistorikken'). Tilsvarende formuleringer accepteres."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilken dokumentation en ansøger med medfødt funktionsnedsættelse kan sende, uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde (hverken vejledning, afsnit eller bestemmelse). Reglen om manglende kilde giver not_met."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Indholdet svarer til vejledningens afsnit 4.3. Der er ikke tilføjet nye regler, betingelser eller retsvirkninger."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at de seneste foreliggende oplysninger kan være ældre, fordi nyere dokumentation ofte mangler ved medfødt funktionsnedsættelse. Det nævner heller ikke, at eksemplerne ikke er kumulative krav, eller at den personlige redegørelse kun supplerer og ikke ophæver det lægefaglige dokumentationsminimum. 'Kan sende' markerer delvist, at listen ikke er obligatorisk, men de to krævede forbehold er ikke udtrykt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en sammenhængende opregning uden indre modsigelser, og den afsluttende bemærkning om den personlige redegørelse følger logisk af listen."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'kan' og 'eventuelle' om dokumentationen, hvilket svarer til vejledningens 'kan f.eks.' og 'evt.'. Det gør ingen eksempler obligatoriske. Vejledningens 'det er vigtigt' er ikke gengivet, men det gør ikke noget forkert absolut."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "partial",
      "reason": "Svaret dækker sygehistorik/journalnotater og den personlige redegørelse. Det nævner ikke eksplicit, at medfødt funktionsnedsættelse typisk er diagnosticeret i barndommen, og at nyere dokumentation om aktuelt funktionsniveau ofte mangler. Det angiver heller ikke eksempler på medfødte funktionsnedsættelser eller at listen ikke er udtømmende."
    },
    "A35": {
      "label": "yes",
      "reason": "Svaret dækker de alternative dokumentationsformer i afsnit 4.3: seneste lægefaglige oplysninger om udrednings- og behandlingsforløb og symptomer, epikriser og journalnotater, støtteafgørelser, skånehensyn og den personlige redegørelse, hvis dokumentation mangler."
    }
  },
  "overall_notes": "Indholdet er juridisk korrekt og dækker de kritiske elementer, men svaret nævner ingen kilder, og de to krævede forbehold mangler: at de seneste oplysninger kan være ældre, og at den personlige redegørelse kun supplerer det lægefaglige minimum."
}

